<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {ONBOARDING_STEPS,type OnboardingProgress,type OnboardingStep} from '../state/onboarding'
const props=defineProps<{open:boolean;progress:OnboardingProgress;readOnly?:boolean;cloud?:boolean;hasDiagram?:boolean;canInvite?:boolean;working?:boolean;message?:string}>()
const emit=defineEmits<{close:[];later:[];skip:[step:OnboardingStep];action:[action:'create'|'connect'|'verify'|'create-team'|'members'];select:[step:OnboardingStep]}>()
const panel=ref<HTMLElement>(),labels={create:'任务与图形',connect:'连接 Agent',alternate:'交替编辑',team:'团队协作'}
const ended=computed(()=>ONBOARDING_STEPS.every(step=>props.progress.steps[step]!=='pending'))
const completedCount=computed(()=>ONBOARDING_STEPS.filter(step=>props.progress.steps[step]==='completed').length)
let returnTo:HTMLElement|undefined
function keyboard(event:KeyboardEvent){if(!props.open)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('close')}if(event.key==='Tab'&&panel.value){const nodes=[...panel.value.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')];const index=nodes.indexOf(document.activeElement as HTMLButtonElement);if(event.shiftKey&&index<=0){event.preventDefault();nodes.at(-1)?.focus()}else if(!event.shiftKey&&(index===nodes.length-1||index<0)){event.preventDefault();nodes[0]?.focus()}}}
watch(()=>props.open,async open=>{if(open){returnTo=document.activeElement instanceof HTMLElement?document.activeElement:undefined;window.addEventListener('keydown',keyboard,true);await nextTick();panel.value?.querySelector<HTMLButtonElement>('button')?.focus()}else{window.removeEventListener('keydown',keyboard,true);if(returnTo?.isConnected)returnTo.focus()}},{immediate:true})
onBeforeUnmount(()=>window.removeEventListener('keydown',keyboard,true))
</script>
<template><div v-if="open" class="studio-overlay flymind-tour-overlay" @click.self="$emit('close')"><section ref="panel" class="studio-dialog flymind-tour" role="dialog" aria-modal="true" aria-label="新手引导"><header class="studio-dialog-heading"><h2>开始使用 FlyMind</h2><button class="studio-icon" aria-label="关闭引导" @click="$emit('close')">×</button></header>
 <nav class="flymind-tour-steps" aria-label="引导步骤"><button v-for="(step,index) in ONBOARDING_STEPS" :key="step" :aria-current="progress.step===step?'step':undefined" @click="$emit('select',step)"><span>{{progress.steps[step]==='completed'?'✓':index+1}}</span>{{labels[step]}}<small>{{progress.steps[step]==='completed'?'已完成':progress.steps[step]==='skipped'?'已跳过':''}}</small></button></nav>
 <div class="flymind-tour-body"><template v-if="ended"><h3>引导已结束</h3><p>已完成 {{completedCount}} 步，已跳过 {{ONBOARDING_STEPS.length-completedCount}} 步。</p></template><template v-else-if="progress.step==='create'"><h3>为当前任务创建图形</h3><p>输入名称并选择图形类型即可创建，分组可选。</p><button class="studio-primary" :disabled="readOnly||working" @click="$emit('action','create')">{{readOnly?'当前空间只读，可跳过':'打开新建图形'}}</button></template>
 <template v-else-if="progress.step==='connect'"><h3>连接你的 Agent</h3><p>按连接窗口在 Codex 或 WorkBuddy 中授权。此步由你明确确认，不自动核验客户端。</p><button class="studio-primary" :disabled="working" @click="$emit('action','connect')">连接 Agent</button></template>
 <template v-else-if="progress.step==='alternate'"><h3>在同一张图中交替编辑</h3><p>先人工修改并保存，再让已授权的 Agent 读取这张图的最新修订并修改，不要另建副本。</p><p v-if="!hasDiagram">请先创建或选择图形。</p><p v-if="readOnly">当前角色只能查看，请切换有编辑权限的空间完成此步。</p><div class="flymind-tour-actions"><button class="studio-primary" :disabled="!hasDiagram||readOnly||working" @click="$emit('close')">去画布编辑</button><button class="studio-secondary" :disabled="!hasDiagram||readOnly||working" @click="$emit('action','connect')">让 Agent 修改此图</button></div><button class="studio-text-btn" :disabled="!hasDiagram||!cloud||readOnly||working" @click="$emit('action','verify')">{{working?'检查中…':'检查实际修改记录'}}</button><p v-if="!cloud">远程协作请先进入云端空间并显式导入本地图形。</p></template>
 <template v-else><h3>与你的团队一起绘图</h3><p>创建团队，或在成员窗口邀请已有账号。</p><div class="flymind-tour-actions"><button class="studio-primary" :disabled="working" @click="$emit('action','create-team')">{{cloud?'创建团队':'进入云端'}}</button><button v-if="cloud&&canInvite" class="studio-secondary" :disabled="working" @click="$emit('action','members')">邀请成员</button></div></template>
 <p v-if="message" class="flymind-tour-message" role="status">{{message}}</p></div>
 <footer class="flymind-tour-footer"><button v-if="ended" class="studio-primary" @click="$emit('close')">完成引导</button><template v-else><button class="studio-text-btn" :disabled="working" @click="$emit('later')">暂时跳过全部</button><button class="studio-secondary" :disabled="working" @click="$emit('skip',progress.step)">跳过此步</button></template></footer>
 </section></div></template>
